def _to_linecol(self) -> tuple[int, int]:
    # Only "\n" ends a line in TOML. "\r\n" is split on the "\n", leaving the
    # "\r" in the line so that every line's length matches its index span.
    # str.splitlines() is not used: it drops the "\r" and also breaks on
    # other characters, which skews the reported line and column.
    lines = self.split("\n")
    cur = 0
    for i, line in enumerate(lines):
        if cur + len(line) + 1 > self.idx:
            return (i + 1, self.idx - cur)

        cur += len(line) + 1

    return len(lines), 0

